import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Check, X, Mail } from 'lucide-react';

const API_BASE_URL = window.location.hostname === 'localhost'
    ? 'http://localhost:3001'
    : 'https://requena-backend-production.up.railway.app';

const AdminVacations = () => {
    const [requests, setRequests] = useState([]);
    const [pendingCount, setPendingCount] = useState(0);
    const [comments, setComments] = useState({});
    const navigate = useNavigate();

    const fetchVacationRequests = async () => {
        try {
            const response = await fetch(`${API_BASE_URL}/admin/vacation-requests`);
            const data = await response.json();

            if (!Array.isArray(data)) {
                console.error('Respuesta inesperada del servidor:', data);
                setRequests([]);
                return;
            }

            setRequests(data);
            setPendingCount(data.filter(req => req.status === 'pending').length);
        } catch (error) {
            console.error('Error fetching vacation requests:', error);
            setRequests([]);
        }
    };

    useEffect(() => {
        fetchVacationRequests();
    }, []);

    const handleStatusChange = async (requestId, status) => {
        try {
            const response = await fetch(`${API_BASE_URL}/admin/update-vacation-request/${requestId}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    status,
                    comments: comments[requestId] || ''
                }),
            });

            if (response.ok) {
                fetchVacationRequests();
                alert(`Solicitud ${status === 'approved' ? 'aprobada' : 'rechazada'} correctamente`);
            }
        } catch (error) {
            console.error('Error updating request:', error);
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 p-6">
            <div className="flex items-center mb-6 gap-4">
                <button
                    onClick={() => navigate('/admin')}
                    className="w-10 h-10 rounded-lg bg-red-600 text-white shadow hover:bg-red-700 transition flex-shrink-0"
                >
                    <svg className="w-5 h-5 mx-auto" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" />
                    </svg>
                </button>
                <h1 className="text-3xl font-bold text-gray-800">Gestión de Vacaciones</h1>
                {pendingCount > 0 && (
                    <span className="bg-red-500 text-white rounded-full px-2 py-1 text-xs">
                        {pendingCount}
                    </span>
                )}
            </div>

            <div className="bg-white shadow-lg rounded-lg overflow-hidden">
                <div className="bg-requena-red p-4">
                    <h2 className="text-xl font-semibold text-white">Solicitudes Pendientes</h2>
                </div>

                <table className="w-full">
                    <thead className="bg-red-50">
                    <tr>
                        <th className="p-3 text-left">Empleado</th>
                        <th className="p-3 text-left">Fecha</th>
                        <th className="p-3 text-left">Estado</th>
                        <th className="p-3 text-left">Comentarios</th>
                        <th className="p-3 text-left">Acciones</th>
                    </tr>
                    </thead>
                    <tbody>
                    {requests.map(request => (
                        <tr key={request.id} className="border-b hover:bg-gray-50">
                            <td className="p-3">{request.user_name}</td>
                            <td className="p-3">{new Date(request.vacation_date).toLocaleDateString()}</td>
                            <td className="p-3">
                                <span className={`px-2 py-1 rounded-full text-xs ${
                                    request.status === 'approved' ? 'bg-green-100 text-green-800' :
                                        request.status === 'rejected' ? 'bg-red-100 text-red-800' :
                                            'bg-yellow-100 text-yellow-800'
                                }`}>
                                    {request.status === 'approved' ? 'Aprobado' :
                                        request.status === 'rejected' ? 'Rechazado' : 'Pendiente'}
                                </span>
                            </td>
                            <td className="p-3">
                                {request.status !== 'pending' && request.comments && (
                                    <div className="text-sm text-gray-600">{request.comments}</div>
                                )}
                                {request.status === 'pending' && (
                                    <textarea
                                        placeholder="Comentarios (opcional)"
                                        className="w-full p-2 border rounded text-sm"
                                        onChange={(e) => setComments({
                                            ...comments,
                                            [request.id]: e.target.value
                                        })}
                                    />
                                )}
                            </td>
                            <td className="p-3">
                                {request.status === 'pending' && (
                                    <div className="flex gap-2">
                                        <button
                                            onClick={() => handleStatusChange(request.id, 'approved')}
                                            className="bg-green-500 text-white p-2 rounded hover:bg-green-600"
                                        >
                                            <Check size={16} />
                                        </button>
                                        <button
                                            onClick={() => handleStatusChange(request.id, 'rejected')}
                                            className="bg-red-500 text-white p-2 rounded hover:bg-red-600"
                                        >
                                            <X size={16} />
                                        </button>
                                    </div>
                                )}
                            </td>
                        </tr>
                    ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default AdminVacations;
